pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller callerContract;

    function setUp() public { c = new C(address(this), address(this)); callerContract = new Caller(); }

    // General rule: for any caller (EOA or contract) the owner() getter should return the stored owner address (set at construction to address(this) in setUp).
    // We fuzz the caller address to exercise calls coming from different msg.sender/tx.origin combinations by having a contract forward the call using delegatecall or call.
    function testFuzz_property(address forwarder, bool useContractForwarder) public {
        // keep forwarder within valid non-zero addresses to make calldata meaningful; allow zero too but that's fine
        // Deploy a forwarding contract at the fuzzed address if requested: we cannot control address of deployment, so instead we use either an EOA pranked caller or our deployed Caller contract.

        // Decide which actor will invoke c.owner(): either an EOA (pranked address = forwarder) or the deployed Caller contract which will call c.owner() via an external call.
        address actor;
        if (useContractForwarder) {
            actor = address(callerContract);
        } else {
            // If the fuzzed address is the zero address, use address(1) instead to keep it a valid EOA
            actor = forwarder == address(0) ? address(1) : forwarder;
        }

        // Ensure the stored owner is what was set by constructor: setUp used address(this) as owner
        address storedOwner = c.owner();

        // Now perform the external call to c.owner() from the chosen actor and observe the returned address.
        bool ok;
        address returned;

        if (useContractForwarder) {
            // Caller contract will call c.owner() and return the result to us
            (ok, returned) = callerContract.callOwner(address(c));
        } else {
            // simulate an EOA calling owner()
            vm.prank(actor);
            try c.owner() returns (address r) {
                ok = true;
                returned = r;
            } catch {
                ok = false;
                returned = address(0);
            }
        }

        // The one asserted property: for ALL inputs the reference returns the stored owner address when owner() is invoked by any caller.
        // Fetching c.owner() via an external call should succeed and equal the stored owner. We assert that the call succeeded and returned the stored owner.
        assertTrue(ok && returned == storedOwner);
    }
}

// Minimal helper that makes an external call to C.owner() and returns whether it succeeded and the returned address.
contract Caller {
    function callOwner(address target) external returns (bool, address) {
        try C(payable(target)).owner() returns (address r) {
            return (true, r);
        } catch {
            return (false, address(0));
        }
    }
}

