pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller helper;

    function setUp() public { c = new C(address(this), address(this)); helper = new Caller(); }

    // fuzz the caller address used to perform the external call through the helper contract
    function testFuzz_property(address callerEOA) public {
        // Keep domain wide but avoid the zero address for clearer tx.origin semantics
        if (callerEOA == address(0)) callerEOA = address(0x1);

        // The rule: for any caller (EOA or contract) making an external CALL to c.owner(),
        // the returned address must equal the owner stored at construction (which is address(this) set in setUp()).
        // We invoke owner() via an intermediate contract (helper) that will perform the CALL with msg.sender set to the helper,
        // but tx.origin will be the externally-owned account that triggers the helper. The correct contract returns the stored owner,
        // while the mutant returns tx.origin and will differ when tx.origin != stored owner.

        // Fund the fuzzed EOA so it can call the helper
        vm.deal(callerEOA, 1 ether);

        // Make the EOA call the helper which in turn performs the external call to c.owner()
        // We capture whether the external call completed and what it returned.
        vm.prank(callerEOA);
        (bool ok, bytes memory ret) = address(helper).call(abi.encodeWithSelector(Caller.callOwner.selector, address(c)));

        // The reference contract never reverts on owner(); both versions return an address.
        // Ensure the call succeeded (it should). If it didn't, that's outside admissible domain; treat as failing the assumption.
        require(ok, "helper call failed");

        address returned = abi.decode(ret, (address));

        // The stored owner in C was set at construction to address(this) (the test contract). Query via a direct view call.
        address storedOwner = c.owner();

        // Universal property: for ANY callerEOA, when owner() is invoked (even through an intermediate contract),
        // the correct contract returns the stored owner. The mutant returning tx.origin will differ when callerEOA != storedOwner.
        // Assert that the value returned through the helper equals the stored owner. This holds for the reference for all inputs
        // and is violated by the mutant for some callerEOA (specifically any EOA not equal to storedOwner).
        assertTrue(returned == storedOwner);
    }
}

// Minimal helper contract that performs an external call to owner() on target and returns the result
contract Caller {
    function callOwner(address target) external returns (address) {
        (bool ok, bytes memory ret) = target.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return abi.decode(ret, (address));
    }
}

