pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerForwarder {
    address public target;
    constructor(address _target) {
        target = _target;
    }
    // simple forwarder: call owner() on target using a regular external call
    function callOwner() external returns (address) {
        (bool ok, bytes memory ret) = target.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return abi.decode(ret, (address));
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the external EOA that will be tx.origin when it calls through a contract
    function testFuzz_property(address callerEOA) public {
        // Keep admissible domain wide but avoid the zero address for clarity
        vm.assume(callerEOA != address(0));

        // Deploy a forwarder contract that will be the immediate msg.sender when calling c.owner()
        CallerForwarder forwarder = new CallerForwarder(address(c));

        // Make an external call from the fuzzed EOA to the forwarder so that tx.origin == callerEOA
        // We need to fund the EOA to be able to send a transaction
        vm.deal(callerEOA, 1 ether);
        vm.prank(callerEOA);
        address returned = forwarder.callOwner();

        // The reference C always returns the stored owner (deployer, set to address(this) in setUp())
        address expectedOwner = c.owner();

        // Exactly one assertion: for the reference contract this holds for all callerEOA; the mutant that uses tx.origin
        // will return callerEOA when called through the forwarder, so for callerEOA != expectedOwner the mutant will differ.
        assertTrue(returned == expectedOwner);
    }
}
